CREATE TABLE migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE workspace_meta(singleton_id INTEGER PRIMARY KEY CHECK(singleton_id=1),workspace_id TEXT NOT NULL,origin_profile TEXT NOT NULL CHECK(origin_profile IN ('desktop','server')),initialized_at TEXT NOT NULL);
CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','agent','requester')),disabled INTEGER NOT NULL DEFAULT 0 CHECK(disabled IN (0,1)),revision INTEGER NOT NULL DEFAULT 1,credentials_version INTEGER NOT NULL DEFAULT 1,authorization_version INTEGER NOT NULL DEFAULT 1,password_hash BLOB NOT NULL,password_salt BLOB NOT NULL,password_iterations INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),credentials_version INTEGER NOT NULL,authorization_version INTEGER NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE tickets(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT NOT NULL,requester_id INTEGER NOT NULL REFERENCES users(id),assignee_id INTEGER REFERENCES users(id),category TEXT NOT NULL CHECK(category IN ('account','billing','technical','other')),priority TEXT NOT NULL CHECK(priority IN ('low','normal','high','urgent')),status TEXT NOT NULL CHECK(status IN ('open','in_progress','awaiting_review','resolved')),revision INTEGER NOT NULL DEFAULT 1,content_version INTEGER NOT NULL DEFAULT 1,conversation_version INTEGER NOT NULL DEFAULT 1,cycle_no INTEGER NOT NULL DEFAULT 1,active_job_id INTEGER REFERENCES jobs(id) DEFERRABLE INITIALLY DEFERRED,approved_reply_id INTEGER REFERENCES reviews(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,resolved_at TEXT);
CREATE INDEX tickets_requester ON tickets(requester_id,id DESC);
CREATE INDEX tickets_status ON tickets(status,id DESC);
CREATE TABLE comments(id INTEGER PRIMARY KEY AUTOINCREMENT,ticket_id INTEGER NOT NULL REFERENCES tickets(id),cycle_no INTEGER NOT NULL,author_id INTEGER NOT NULL REFERENCES users(id),visibility TEXT NOT NULL CHECK(visibility IN ('public','internal')),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX comments_ticket ON comments(ticket_id,id);
CREATE TABLE knowledge_articles(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT NOT NULL,tags_json TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,ticket_id INTEGER NOT NULL REFERENCES tickets(id),actor_id INTEGER NOT NULL REFERENCES users(id),actor_authorization_version INTEGER NOT NULL,parent_job_id INTEGER REFERENCES jobs(id),input_json TEXT NOT NULL,config_json TEXT NOT NULL,encrypted_secret BLOB,status TEXT NOT NULL CHECK(status IN ('queued','running','succeeded','failed','canceled','stale')),error_code TEXT,error_stage TEXT,request_id TEXT NOT NULL,created_at TEXT NOT NULL,started_at TEXT,finished_at TEXT);
CREATE UNIQUE INDEX jobs_one_active ON jobs(ticket_id) WHERE status IN ('queued','running');
CREATE INDEX jobs_state ON jobs(status,id);
CREATE TABLE job_steps(job_id INTEGER NOT NULL REFERENCES jobs(id),ordinal INTEGER NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,PRIMARY KEY(job_id,ordinal));
CREATE TABLE model_calls(job_id INTEGER NOT NULL REFERENCES jobs(id),ordinal INTEGER NOT NULL,call_json TEXT NOT NULL,PRIMARY KEY(job_id,ordinal));
CREATE TABLE connection_tests(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER NOT NULL REFERENCES users(id),call_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE job_source_snapshots(job_id INTEGER NOT NULL REFERENCES jobs(id),article_id INTEGER NOT NULL REFERENCES knowledge_articles(id),evidence_id TEXT NOT NULL,version INTEGER NOT NULL,title TEXT NOT NULL,excerpt TEXT NOT NULL,body_hash TEXT NOT NULL,PRIMARY KEY(job_id,evidence_id));
CREATE TABLE drafts(id INTEGER PRIMARY KEY AUTOINCREMENT,job_id INTEGER NOT NULL UNIQUE REFERENCES jobs(id),ticket_id INTEGER NOT NULL REFERENCES tickets(id),content_version INTEGER NOT NULL,conversation_version INTEGER NOT NULL,cycle_no INTEGER NOT NULL,provider_mode TEXT NOT NULL CHECK(provider_mode IN ('demo','live')),output_json TEXT NOT NULL,context_omitted INTEGER NOT NULL,warning_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX drafts_ticket ON drafts(ticket_id,id DESC);
CREATE TABLE draft_sources(draft_id INTEGER NOT NULL REFERENCES drafts(id),article_id INTEGER NOT NULL REFERENCES knowledge_articles(id),evidence_id TEXT NOT NULL,version INTEGER NOT NULL,title TEXT NOT NULL,excerpt TEXT NOT NULL,body_hash TEXT NOT NULL,PRIMARY KEY(draft_id,evidence_id));
CREATE TABLE reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,ticket_id INTEGER NOT NULL REFERENCES tickets(id),cycle_no INTEGER NOT NULL,draft_id INTEGER REFERENCES drafts(id),actor_id INTEGER NOT NULL REFERENCES users(id),decision TEXT NOT NULL CHECK(decision IN ('approved','rejected','manual')),reason_code TEXT,reply_text TEXT,ack_json TEXT NOT NULL,review_context_json TEXT NOT NULL,content_version INTEGER NOT NULL,conversation_version INTEGER NOT NULL,original_reply_hash TEXT,text_changed INTEGER,created_at TEXT NOT NULL);
CREATE UNIQUE INDEX reviews_draft_once ON reviews(draft_id) WHERE draft_id IS NOT NULL;
CREATE INDEX reviews_ticket ON reviews(ticket_id,id DESC);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,ticket_id INTEGER REFERENCES tickets(id),actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,details_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX audit_ticket ON audit_events(ticket_id,id DESC);
CREATE TABLE ai_settings(singleton_id INTEGER PRIMARY KEY CHECK(singleton_id=1),config_json TEXT NOT NULL,encrypted_key BLOB,version INTEGER NOT NULL);
CREATE TABLE idempotency(actor_id INTEGER NOT NULL REFERENCES users(id),route TEXT NOT NULL,key_hash TEXT NOT NULL,request_hash TEXT NOT NULL,status INTEGER NOT NULL,response_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(actor_id,route,key_hash));
CREATE INDEX idempotency_expiry ON idempotency(created_at);
CREATE TABLE runtime_probe(singleton_id INTEGER PRIMARY KEY CHECK(singleton_id=1),probe_seq INTEGER NOT NULL);
INSERT INTO runtime_probe VALUES(1,0);
CREATE TABLE keystore_recoveries(action_id TEXT PRIMARY KEY,new_key_fingerprint TEXT NOT NULL,committed_at TEXT NOT NULL);

